"""Generate the dbt test that holds every aggregate binding to the detail.

An aggregate source that binds a metric claims the same answer as the detail under
its content filter. This module asks the compiler for both sides of that claim and
emits one singular dbt test that fails on any difference:

- a navigable source: every group at its content levels equals the detail's group,
  and neither side holds a group the other lacks (a full join), so a wrong role or
  key mapping fails even when the totals agree;
- a source that is not navigable (a population no row filter states, such as a
  floor): each group it holds equals the detail's group; the detail's other groups
  are the floor's to drop (a left join from the source).

The test is generated, so the claim and its check cannot drift apart: changing a
content filter, a content level or a binding changes the test with it.
"""

import ossie_compile
from ossie_compile import Model, Query, _payload

TEST_FILE = "assert_semantic_content_holds.sql"
HEADER = """-- GENERATED by the semantic-model skill's ossie.py. Do not edit:
-- change the logical sources in the semantic model and regenerate.
--
-- Every aggregate source that binds a metric claims the detail's answer under its
-- content filter, group by group at its content levels. Each comparison below is the
-- compiler's SQL for the aggregate and for the detail; a returned row is a binding
-- that does not hold.
"""

EXACT_TYPES = {"Integer"}


def dbt_relation(table):
    return "{{ ref('" + table["dbt_model"] + "') }}"


def _differs(model, metric, left, right):
    """A predicate true when two values of `metric` disagree.

    A SUM reads a missing group as zero, so a source densified on a spine (a zero row
    the detail has no group for) holds. A non-integral value may differ by float noise
    of up to a cent.
    """
    if model.aggregation(metric) == "SUM":
        left, right = f"coalesce({left}, 0)", f"coalesce({right}, 0)"
    if model.metrics[metric].get("datatype") in EXACT_TYPES:
        return f"{left} is distinct from {right}"
    return f"(({left} is null) <> ({right} is null) or abs({left} - {right}) > 0.01)"


def _bound_metrics(model, src):
    out = []
    for name in src.get("column_map") or {}:
        if name in model.metrics and not _payload(model.metrics[name]).get("derived_expression") \
                and model.aggregation(name) in ossie_compile.ROLLUPS:
            out.append(name)
    return out


def _source_checks(model, fact, src, n):
    metrics = _bound_metrics(model, src)
    if not metrics:
        return [], []
    label = f"{fact}.{src['name']}"
    content = src.get("content_filter")
    levels = [{k: v for k, v in ref.items() if k != "key_columns"}
              for ref in src.get("content_levels") or []]
    held = ossie_compile.compile_query(model, Query(metrics, levels, content, src["name"]))
    detail = ossie_compile.compile_query(model, Query(metrics, levels, content, "detail"))
    keys = [c for c in held.columns if c not in metrics]
    ctes = [f"s{n}_source as (\n{held.sql}\n)", f"s{n}_detail as (\n{detail.sql}\n)"]
    if src.get("navigable", True):
        join = "full join"
        member = [f"coalesce(s.{k}, d.{k})" for k in keys]
    else:
        join = "left join"
        member = [f"s.{k}" for k in keys]
    on = " and ".join(f"s.{k} is not distinct from d.{k}" for k in keys) or "true"
    at = " || '|' || ".join(f"coalesce(cast({m} as varchar), '')" for m in member)

    def binding(metric):
        return f"'{label}.{metric} at ' || {at}" if keys else f"'{label}.{metric}'"

    checks = [f"select {binding(m)} as binding,\n"
              f"    cast(s.{m} as varchar) as source_value,\n"
              f"    cast(d.{m} as varchar) as detail_value\n"
              f"from s{n}_source as s {join} s{n}_detail as d on {on}\n"
              f"where {_differs(model, m, f's.{m}', f'd.{m}')}"
              for m in metrics]
    return ctes, checks


def generate(docs):
    """SQL for every aggregate binding in `docs` (parsed dicts)."""
    ctes, checks, n = [], [], 0
    for doc in docs:
        model = Model(doc, dbt_relation)
        for fact in model.datasets:
            for src in model.sources(fact):
                if src.get("priority_group", 1) != 0:
                    continue
                n += 1
                more_ctes, more_checks = _source_checks(model, fact, src, n)
                ctes += more_ctes
                checks += more_checks
    if not checks:
        return HEADER + "\nselect null as binding, null as source_value, null as detail_value where false\n"
    return (HEADER + "\nwith " + ",\n\n".join(ctes) + "\n\n"
            + "\n\nunion all\n\n".join(checks) + "\n")
